package ru.practicum.request;

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import ru.practicum.request.model.ItemRequest;

import java.util.List;

public interface RequestRepository extends JpaRepository<ItemRequest, Long> {

    @Query("SELECT r FROM ItemRequest r WHERE r.requestor.id = :userId ORDER BY r.created DESC")
    List<ItemRequest> findByRequestorId(@Param("userId") long userId);

    @Query("SELECT r FROM ItemRequest r WHERE r.requestor.id <> :userId ORDER BY r.created DESC")
    List<ItemRequest> findAllExceptUserId(@Param("userId") long userId);
}

package ru.practicum.request.mapper;

import ru.practicum.request.model.ItemRequest;
import ru.practicum.request.model.ItemRequestDto;

public class RequestMapper {

    public static ItemRequest toEntity(ItemRequestDto dto) {
        if (dto == null) {
            return null;
        }

        ItemRequest itemRequest = new ItemRequest();
        itemRequest.setId(dto.getId());
        itemRequest.setDescription(dto.getDescription());
        return itemRequest;
    }

    public static ItemRequestDto toDto(ItemRequest entity) {
        if (entity == null) {
            return null;
        }

        ItemRequestDto dto = new ItemRequestDto();
        dto.setId(entity.getId());
        dto.setDescription(entity.getDescription());
        dto.setRequestor(entity.getRequestor().getId());
        return dto;
    }
}

